#import "TFAIISHRootCatalog.h"
#import <CommonCrypto/CommonDigest.h>
static NSError *CatalogError(NSString *message){return [NSError errorWithDomain:@"Dylix.RootCatalog" code:1 userInfo:@{NSLocalizedDescriptionKey:message}];}
static NSString *CatalogDirectory(void){NSString *base=[NSSearchPathForDirectoriesInDomains(NSApplicationSupportDirectory,NSUserDomainMask,YES).firstObject.stringByResolvingSymlinksInPath stringByAppendingPathComponent:@"Dylix/RootArchives"];if(![base isEqual:base.stringByResolvingSymlinksInPath])return nil;if(![NSFileManager.defaultManager createDirectoryAtPath:base withIntermediateDirectories:YES attributes:@{NSFilePosixPermissions:@0700} error:nil])return nil;return base;}
static NSString *DigestFile(NSString *path){NSInputStream *input=[NSInputStream inputStreamWithFileAtPath:path];[input open];CC_SHA256_CTX ctx;CC_SHA256_Init(&ctx);uint8_t buffer[65536];NSInteger n;while((n=[input read:buffer maxLength:sizeof(buffer)])>0)CC_SHA256_Update(&ctx,buffer,(CC_LONG)n);[input close];if(n<0)return nil;unsigned char digest[32];CC_SHA256_Final(digest,&ctx);NSMutableString *text=[NSMutableString new];for(int i=0;i<32;i++)[text appendFormat:@"%02x",digest[i]];return text;}
static BOOL SessionKeyValid(NSString *key){return key.length==64&&[key rangeOfCharacterFromSet:[NSCharacterSet characterSetWithCharactersInString:@"0123456789abcdef"].invertedSet].location==NSNotFound;}
@interface TFAIISHRootCatalog ()
@property NSURLSession *session;
@property NSURLSessionDownloadTask *task;
@property NSDictionary *entry;
@property(copy) void(^progress)(double);
@property(copy) void(^completion)(NSError *);
@property BOOL terminal;
@end
@implementation TFAIISHRootCatalog
+ (instancetype)shared{static id shared;static dispatch_once_t once;dispatch_once(&once,^{shared=[self new];});return shared;}
+ (NSArray *)catalog{return @[@{@"id":@"alpine-3.21.0",@"version":@"3.21.0",@"sha256":@"f31202c4070c4ef7de9e157e1bd01cb4da3a2150035d74ea5372c5e86f1efac1",@"url":@"https://dl-cdn.alpinelinux.org/alpine/v3.21/releases/aarch64/alpine-minirootfs-3.21.0-aarch64.tar.gz",@"bundled":@YES},@{@"id":@"alpine-3.22.0",@"version":@"3.22.0",@"sha256":@"74eaa1f80aceb35a69f26a7772cd22848a51921323a32b2ae057b2a4c8188fd5",@"url":@"https://dl-cdn.alpinelinux.org/alpine/v3.22/releases/aarch64/alpine-minirootfs-3.22.0-aarch64.tar.gz",@"bundled":@NO}];}
+ (NSDictionary *)cacheInfo:(NSString *)identifier{NSDictionary *entry=nil;for(NSDictionary *row in self.catalog)if([row[@"id"] isEqual:identifier])entry=row;if(!entry)return @{};NSString *path=[entry[@"bundled"] boolValue]?[NSBundle.mainBundle pathForResource:@"alpine-minirootfs-3.21.0-aarch64" ofType:@"tar.gz" inDirectory:@"iSH"]:[CatalogDirectory() stringByAppendingPathComponent:[identifier stringByAppendingString:@".tar.gz"]];NSDictionary *a=path?[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil]:nil;BOOL valid=[a[NSFileType] isEqual:NSFileTypeRegular]&&[path isEqual:path.stringByResolvingSymlinksInPath]&&[DigestFile(path) isEqual:entry[@"sha256"]];return @{@"cached":@(valid),@"bytes":a[NSFileSize]?:@0,@"bundled":entry[@"bundled"]};}
+ (BOOL)removeArchive:(NSString *)identifier error:(NSError **)error{TFAIISHRootCatalog *catalog=[self shared];NSDictionary *entry=nil;for(NSDictionary *row in self.catalog)if([row[@"id"] isEqual:identifier])entry=row;if(!entry||[entry[@"bundled"] boolValue]||([catalog.entry[@"id"] isEqual:identifier]&&catalog.task)){if(error)*error=CatalogError(@"内置资源或正在下载的归档不可删除");return NO;}for(NSString *suffix in @[@".tar.gz",@".resume",@".tar.gz.staging"]){NSString *path=[CatalogDirectory() stringByAppendingPathComponent:[identifier stringByAppendingString:suffix]];if([NSFileManager.defaultManager fileExistsAtPath:path]&&![NSFileManager.defaultManager removeItemAtPath:path error:error])return NO;}return YES;}
+ (NSDictionary *)selection:(NSString *)key{NSString *selected=SessionKeyValid(key)?[NSUserDefaults.standardUserDefaults stringForKey:[@"DylixRootVersion-" stringByAppendingString:key]]:nil;for(NSDictionary *entry in self.catalog)if([entry[@"id"] isEqual:selected])return entry;return self.catalog.firstObject;}
+ (NSString *)archive:(NSString *)key error:(NSError **)error{NSDictionary *entry=[self selection:key];NSString *path=[entry[@"bundled"] boolValue]?[NSBundle.mainBundle pathForResource:@"alpine-minirootfs-3.21.0-aarch64" ofType:@"tar.gz" inDirectory:@"iSH"]:[CatalogDirectory() stringByAppendingPathComponent:[entry[@"id"] stringByAppendingString:@".tar.gz"]];NSDictionary *attrs=path?[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil]:nil;if(![attrs[NSFileType] isEqual:NSFileTypeRegular]||![path isEqual:path.stringByResolvingSymlinksInPath]||![DigestFile(path) isEqual:entry[@"sha256"]]){if(error)*error=CatalogError(@"rootfs 缺失或官方固定哈希不符；未切换环境。");return nil;}return path;}
+ (BOOL)select:(NSString *)identifier sessionKey:(NSString *)key error:(NSError **)error{if(!SessionKeyValid(key)){if(error)*error=CatalogError(@"会话标识无效");return NO;}NSDictionary *chosen=nil;for(NSDictionary *entry in self.catalog)if([entry[@"id"] isEqual:identifier])chosen=entry;if(!chosen){if(error)*error=CatalogError(@"版本不在内置官方目录中");return NO;}NSString *setting=[@"DylixRootVersion-" stringByAppendingString:key];NSString *old=[NSUserDefaults.standardUserDefaults stringForKey:setting];[NSUserDefaults.standardUserDefaults setObject:identifier forKey:setting];if(![self archive:key error:error]){if(old)[NSUserDefaults.standardUserDefaults setObject:old forKey:setting];else[NSUserDefaults.standardUserDefaults removeObjectForKey:setting];return NO;}return YES;}
- (void)finish:(NSError *)error{if(self.terminal)return;self.terminal=YES;void(^done)(NSError *)=self.completion;self.completion=nil;self.progress=nil;self.task=nil;[self.session finishTasksAndInvalidate];self.session=nil;if(done)done(error);}
- (void)download:(NSString *)identifier progress:(void(^)(double))progress completion:(void(^)(NSError *))completion{if(self.task){completion(CatalogError(@"已有版本下载，请先等待或取消"));return;}NSDictionary *entry=nil;for(NSDictionary *row in self.class.catalog)if([row[@"id"] isEqual:identifier])entry=row;if(!entry||[entry[@"bundled"] boolValue]){completion(CatalogError(@"请选择可下载的官方版本"));return;}if([self.class cacheInfo:identifier][@"cached"]&&[[self.class cacheInfo:identifier][@"cached"] boolValue]){completion(nil);return;}self.entry=entry;self.terminal=NO;self.progress=progress;self.completion=completion;NSURLSessionConfiguration *config=NSURLSessionConfiguration.ephemeralSessionConfiguration;config.URLCache=nil;config.HTTPCookieStorage=nil;config.timeoutIntervalForResource=180;self.session=[NSURLSession sessionWithConfiguration:config delegate:self delegateQueue:NSOperationQueue.mainQueue];NSString *resume=[CatalogDirectory() stringByAppendingPathComponent:[identifier stringByAppendingString:@".resume"]];NSDictionary *resumeAttrs=[NSFileManager.defaultManager attributesOfItemAtPath:resume error:nil];NSData *data=([resumeAttrs[NSFileType] isEqual:NSFileTypeRegular]&&[resume isEqual:resume.stringByResolvingSymlinksInPath]&&[resumeAttrs[NSFileSize] unsignedLongLongValue]<=1024*1024)?[NSData dataWithContentsOfFile:resume]:nil;self.task=data?[self.session downloadTaskWithResumeData:data]:[self.session downloadTaskWithURL:[NSURL URLWithString:entry[@"url"]]];[self.task resume];}
- (void)cancelDownload{NSString *identifier=self.entry[@"id"];[self.task cancelByProducingResumeData:^(NSData *data){if(data){NSString *path=[CatalogDirectory() stringByAppendingPathComponent:[identifier stringByAppendingString:@".resume"]];[data writeToFile:path options:NSDataWritingAtomic error:nil];[NSFileManager.defaultManager setAttributes:@{NSFilePosixPermissions:@0600} ofItemAtPath:path error:nil];}}];}
- (void)URLSession:(NSURLSession *)session task:(NSURLSessionTask *)task willPerformHTTPRedirection:(NSHTTPURLResponse *)response newRequest:(NSURLRequest *)request completionHandler:(void(^)(NSURLRequest *))handler{handler(nil);}
- (void)URLSession:(NSURLSession *)session downloadTask:(NSURLSessionDownloadTask *)task didWriteData:(int64_t)written totalBytesWritten:(int64_t)total totalBytesExpectedToWrite:(int64_t)expected{if(task!=self.task||self.terminal)return;if(total>32*1024*1024||expected>32*1024*1024){[task cancel];[self finish:CatalogError(@"rootfs 下载超过32 MiB，已停止")];return;}if(self.progress)self.progress(expected>0?(double)total/expected:0);}
- (void)URLSession:(NSURLSession *)session downloadTask:(NSURLSessionDownloadTask *)task didFinishDownloadingToURL:(NSURL *)url{if(task!=self.task||self.terminal)return;NSHTTPURLResponse *response=(id)task.response;NSError *error=nil;if((response.statusCode!=200&&response.statusCode!=206)||![DigestFile(url.path) isEqual:self.entry[@"sha256"]])error=CatalogError(@"HTTP 状态或官方 SHA-256 校验失败，未安装下载内容。");NSString *target=[CatalogDirectory() stringByAppendingPathComponent:[self.entry[@"id"] stringByAppendingString:@".tar.gz"]];if(!error){NSString *stage=[target stringByAppendingString:@".staging"];[NSFileManager.defaultManager removeItemAtPath:stage error:nil];if([NSFileManager.defaultManager copyItemAtPath:url.path toPath:stage error:&error]){if([NSFileManager.defaultManager fileExistsAtPath:target]){NSURL *result=nil;[NSFileManager.defaultManager replaceItemAtURL:[NSURL fileURLWithPath:target] withItemAtURL:[NSURL fileURLWithPath:stage] backupItemName:nil options:0 resultingItemURL:&result error:&error];}else[NSFileManager.defaultManager moveItemAtPath:stage toPath:target error:&error];}if(!error)[NSFileManager.defaultManager removeItemAtPath:[CatalogDirectory() stringByAppendingPathComponent:[self.entry[@"id"] stringByAppendingString:@".resume"]] error:nil];}if(error)[NSFileManager.defaultManager removeItemAtPath:[target stringByAppendingString:@".staging"] error:nil];[NSFileManager.defaultManager removeItemAtPath:[CatalogDirectory() stringByAppendingPathComponent:[self.entry[@"id"] stringByAppendingString:@".resume"]] error:nil];[self finish:error];}
- (void)URLSession:(NSURLSession *)session task:(NSURLSessionTask *)task didCompleteWithError:(NSError *)error{if(!error||self.terminal||task!=self.task)return;if(error.code!=NSURLErrorCancelled&&!error.userInfo[NSURLSessionDownloadTaskResumeData]){[NSFileManager.defaultManager removeItemAtPath:[CatalogDirectory() stringByAppendingPathComponent:[self.entry[@"id"] stringByAppendingString:@".resume"]] error:nil];}[NSFileManager.defaultManager setAttributes:@{NSFilePosixPermissions:@0600} ofItemAtPath:[CatalogDirectory() stringByAppendingPathComponent:[self.entry[@"id"] stringByAppendingString:@".tar.gz"]] error:nil];NSData *resume=error.userInfo[NSURLSessionDownloadTaskResumeData];if(resume){NSString *path=[CatalogDirectory() stringByAppendingPathComponent:[self.entry[@"id"] stringByAppendingString:@".resume"]];[resume writeToFile:path options:NSDataWritingAtomic error:nil];}[self finish:CatalogError(error.code==NSURLErrorCancelled?@"下载已取消，可再次选择继续下载":@"下载中断；可再次选择继续，若续传数据失效请重新下载")];}
@end
